package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.genetics.PredictDb;
import static org.jlinalg.cli.NextflowFiles.*;

/** Capture originals, compute, and independently replay complete saved native results. */
final class MetaxcanBundle {
    static final String PROFILE="metaxcan-native-predictdb-summary-v1";
    static final String PROFILE_V2="metaxcan-native-predictdb-summary-v2";
    static String profile(MetaxcanRequest.Spec spec){return spec.extended()?PROFILE_V2:PROFILE;}
    static final String ACTION="Required action: read WARNINGS.md, OUTPUT-AUDIT.json and every GWAS, matrix, SNP and gene disposition. Require COMPLETED.json and successful metaxcan-tools --verify using the exact producing JAR before downstream use. SKIP3: the selected qualified implementation or permitted SQLite native runtime is unavailable; skip the dependent analysis and supply the named prerequisite where allowed, or retain the skip. FAIL2: invalid/changed input, capacity, cancellation, numerical or finalization failure; no complete result is admitted. Preserve every attempt and correct the cause using NEW paths. Never refresh historical hashes. Hashes establish integrity, not model authenticity, assembly identity or biological accuracy. Cell Ranger remains excluded.";
    private MetaxcanBundle(){ }
    static Pin producer()throws IOException {
        try{Path jar=Path.of(MetaxcanBundle.class.getProtectionDomain().getCodeSource().getLocation().toURI()).toAbsolutePath().normalize();require(Files.isRegularFile(jar),"Run MetaXcan capture/verification using its exact packaged executable JAR");return pin(jar,1000000000L,()->{});}catch(java.net.URISyntaxException e){throw new IOException(e);}
    }
    static Path start(Path request,Path supplied)throws IOException {
        var s=MetaxcanRequest.read(request.toAbsolutePath().normalize(),true);
        if(!s.nativeEngine())throw new MetaxcanRequest.Unavailable("Original MetaXcan execution is not yet admitted by this command. Its legacy runtime/individual formats remain under qualification. For summary data choose the native engine explicitly, or run a separately verified upstream installation; no engine is substituted");
        Path root=supplied.toAbsolutePath().normalize();require(root.getParent()!=null&&root.getParent().toRealPath().equals(root.getParent()),"Require a NEW result directory with canonical existing parent");Pin producer=producer();boolean created=false;String stage="CREATE_CAPTURE";long started=System.nanoTime();Runnable check=bounded(s,started);
        try {
            Files.createDirectory(root);created=true;writeJson(root.resolve("INCOMPLETE.json"),Map.of("analysis_admitted",false));Files.writeString(root.resolve("WARNINGS.md"),warnings(s),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);writeJson(root.resolve("request.json"),s.document());Files.createDirectory(root.resolve("inputs"));Files.createDirectory(root.resolve("inputs/models"));Files.createDirectory(root.resolve("outputs"));
            stage="CAPTURE_COMPLETE_ORIGINAL_INPUTS";var source=new TreeMap<String,Object>();long total=0;
            for(var row:s.originals().entrySet()) {
                check.run();Path original=Path.of(row.getValue());if(row.getKey().endsWith(".db"))PredictDb.requireStandalone(original);Pin before=pin(original,s.capacity().inputBytes(),check);total=Math.addExact(total,before.bytes());require(total<=s.capacity().inputBytes(),"Complete captured inputs exceed input_bytes");Path destination=root.resolve(row.getKey());Files.copy(original,destination);require(before.equals(pin(destination,s.capacity().inputBytes(),check))&&before.equals(pin(original,s.capacity().inputBytes(),check)),"Original/captured input changed during copying");source.put(row.getKey(),Map.of("original",row.getValue(),"pin",before));
            }
            writeJson(root.resolve("source-inputs.json"),Map.of("files",source,"complete_original_bytes",total,"source_bytes_unchanged",true));
            stage="NATIVE_SUMMARY_COMPUTATION";var audit=MetaxcanSummary.run(root,s,false,check);writeJson(root.resolve("OUTPUT-AUDIT.json"),audit);originals(s,source,check);require(producer.equals(producer()),"Producing executable changed during computation");
            stage="FINALIZE_AND_RECOMPUTE_CAPTURE";var files=files(root,s,check);files.remove("INCOMPLETE.json");writeJson(root.resolve("manifest.json"),Map.of("schema_version",1,"profile",profile(s),"files",files,"producer",producer,"analysis_admitted",true,"original_executable_run",false,"whole_paper_reproduced",false));writeJson(root.resolve("COMPLETED.json"),Map.of("schema_version",1,"status","COMPLETE_NATIVE_METAXCAN_CAPTURE","manifest",pin(root.resolve("manifest.json"),16777216,check),"analysis_admitted",true));verify(root,true,check);originals(s,source,check);check.run();Files.delete(root.resolve("INCOMPLETE.json"));return root;
        }catch(IOException|RuntimeException|Error e){if(created)failure(root,stage,e);throw e;}
    }
    static void verify(Path supplied,boolean precommit,Runnable cancellation)throws IOException {
        Path root=supplied.toAbsolutePath().normalize();directory(root);require(!Files.exists(root.resolve("FAILURE.json"),LinkOption.NOFOLLOW_LINKS)&&Files.exists(root.resolve("INCOMPLETE.json"),LinkOption.NOFOLLOW_LINKS)==precommit,"Failed/incomplete MetaXcan capture is not admitted");var done=object(json(root.resolve("COMPLETED.json"),1048576));keys(done,"schema_version","status","manifest","analysis_admitted");integer(done.get("schema_version"),1,1);require("COMPLETE_NATIVE_METAXCAN_CAPTURE".equals(done.get("status"))&&Boolean.TRUE.equals(done.get("analysis_admitted")),"Missing complete native MetaXcan admission");Pin manifest=pin(root.resolve("manifest.json"),16777216,cancellation);require(manifest.equals(fingerprint(done.get("manifest"),16777216)),"MetaXcan manifest bytes changed");var saved=object(json(root.resolve("manifest.json"),16777216));keys(saved,"schema_version","profile","files","producer","analysis_admitted","original_executable_run","whole_paper_reproduced");integer(saved.get("schema_version"),1,1);require(Set.of(PROFILE,PROFILE_V2).contains(saved.get("profile"))&&Boolean.TRUE.equals(saved.get("analysis_admitted"))&&Boolean.FALSE.equals(saved.get("original_executable_run"))&&Boolean.FALSE.equals(saved.get("whole_paper_reproduced")),"Different or expanded native MetaXcan contract");require(producer().equals(fingerprint(saved.get("producer"),1000000000L)),"Restore the exact producing JAR; do not refresh saved hashes");
        var s=MetaxcanRequest.read(root.resolve("request.json"),false);require(s.nativeEngine()&&s.summary()&&profile(s).equals(saved.get("profile")),"Saved native engine/mode/profile differs");Runnable deadline=bounded(s,System.nanoTime());Runnable check=()->{cancellation.run();deadline.run();};
        inventory(root,s,saved.get("files"),precommit,check);var sources=object(json(root.resolve("source-inputs.json"),1048576));keys(sources,"files","complete_original_bytes","source_bytes_unchanged");var sourceFiles=object(sources.get("files"));require(Boolean.TRUE.equals(sources.get("source_bytes_unchanged"))&&sourceFiles.keySet().equals(s.originals().keySet()),"Original source capture population differs");long bytes=0;
        // Original host paths are declarations only during saved verification.
        for(var row:s.originals().entrySet()){var declaration=object(sourceFiles.get(row.getKey()));keys(declaration,"original","pin");require(row.getValue().equals(declaration.get("original")),"Source path declaration differs");Pin actual=pin(root.resolve(row.getKey()),s.capacity().inputBytes(),check);require(actual.equals(fingerprint(declaration.get("pin"),s.capacity().inputBytes())),"Captured original input bytes differ");bytes=Math.addExact(bytes,actual.bytes());}require(bytes==integer(sources.get("complete_original_bytes"),1,s.capacity().inputBytes()),"Complete source byte count differs");
        var recomputed=MetaxcanSummary.run(root,s,true,check);require(NextflowJson.json(recomputed).equals(NextflowJson.json(json(root.resolve("OUTPUT-AUDIT.json"),1048576))),"Saved numeric/population audit differs from complete recomputation");require(Files.readString(root.resolve("WARNINGS.md"),StandardCharsets.UTF_8).equals(warnings(s)),"Warnings and required actions changed");inventory(root,s,saved.get("files"),precommit,check);require(manifest.equals(pin(root.resolve("manifest.json"),16777216,check)),"Manifest changed during full readback");
    }
    static Map<String,Object> files(Path root,MetaxcanRequest.Spec s,Runnable check)throws IOException {
        long max=Math.addExact(Math.addExact(s.capacity().inputBytes(),s.capacity().outputBytes()),16777216);var result=new TreeMap<String,Object>();long generated=0;
        for(var entry:tree(root,256,max,Math.max(s.capacity().inputBytes(),s.capacity().outputBytes())+16777216,check).entrySet()) {
            require(entry.getValue().kind().equals("file"),"MetaXcan captures cannot contain links");var p=entry.getValue().pin();if(!s.originals().containsKey(entry.getKey())){generated=Math.addExact(generated,p.bytes());require(generated<=s.capacity().outputBytes()+16777216,"Complete generated bytes exceed output_bytes plus16MiB metadata reserve");}result.put(entry.getKey(),Map.of("bytes",p.bytes(),"sha256",p.sha256()));
        }return result;
    }
    private static void inventory(Path root,MetaxcanRequest.Spec s,Object declared,boolean precommit,Runnable check)throws IOException {
        var actual=files(root,s,check);var names=new HashSet<>(Set.of("request.json","source-inputs.json","GWAS.jsonl","MATRICES.jsonl","MODEL-SNPS.jsonl","GENES.jsonl","OUTPUT-AUDIT.json","WARNINGS.md","outputs/summary.tsv","manifest.json","COMPLETED.json"));names.addAll(s.originals().keySet());if(s.joint())names.add("outputs/joint.tsv");if(precommit)names.add("INCOMPLETE.json");require(actual.keySet().equals(names),"Missing/extra captured MetaXcan file; the full namespace must match");
        var directories=new HashSet<>(Set.of("","inputs","inputs/models","outputs"));try(var stream=Files.walk(root)){for(Path p:stream.toList())if(Files.isDirectory(p,LinkOption.NOFOLLOW_LINKS))require(directories.remove(root.relativize(p).toString().replace('\\','/')),"Extra captured MetaXcan directory");}require(directories.isEmpty(),"Captured MetaXcan directories are missing");
        actual.remove("manifest.json");actual.remove("COMPLETED.json");actual.remove("INCOMPLETE.json");require(NextflowJson.json(actual).equals(NextflowJson.json(declared)),"Complete captured MetaXcan bytes differ");
    }
    private static void originals(MetaxcanRequest.Spec s,Map<?,?> source,Runnable check)throws IOException {for(var row:s.originals().entrySet()){Path p=Path.of(row.getValue());if(row.getKey().endsWith(".db"))PredictDb.requireStandalone(p);require(pin(p,s.capacity().inputBytes(),check).equals(object(source.get(row.getKey())).get("pin")),"Original source changed before final admission");}}
    private static Runnable bounded(MetaxcanRequest.Spec s,long started){return ()->{if(Thread.currentThread().isInterrupted())throw new IllegalStateException("MetaXcan cancelled");if((System.nanoTime()-started)/1000000>s.capacity().wallMillis())throw new IllegalStateException("Cooperative native MetaXcan wall_millis exceeded");};}
    static String warnings(MetaxcanRequest.Spec s)throws IOException {
        boolean calibrated="source-phi".equals(object(s.settings().get("calibration")).get("mode"));
        String value="METAXCAN WARNINGS AND REQUIRED ACTION\n\n"+(calibrated?"PHI CALIBRATION explicitly selected; require compatible phi for every reported gene. Negative source phi is replaced by zero and counted. Raw uncalibrated values remain visible.":"WARNING: UNCALIBRATED TWAS Z AND P VALUES. Inflation correction was explicitly disabled; do not interpret these as calibrated results.")+"\n\nNative Java engine; exact source behaviour contract "+s.edition()+", mode "+s.mode()+", provider-declared assembly "+s.build()+". No original executable was run. Release tag v0.8.1 has internal package version0.7.5; commit-0.7.4 is an explicit source commit, not a release-tag or author-environment claim.\n\nThe full closed PredictDB databases, GWAS, covariance and optional model-product files are captured unchanged. rsid is the model key; varID selection, identifier remapping, strand complementation, gene-version trimming, model training, genotype imputation, individual-level prediction/association and biological replication remain separate work. GWAS alleles are uppercased as upstream does; only exact allele pairs or swaps match summary data. Palindromic pairs are retained under that explicit source contract. Across-model allele conflicts and duplicate gene/variant weights, extra genes or unordered matrix pairs are refused. No first/last-row selection is inferred. Annotation SNP counts remain distinct from actual weights.\n\nSource statistic precedence is Z then P with effect sign then BETA/SE. OR overwrites BETA whenever declared. Z values are rounded through float32 before allele alignment. The default rsID filter is case-sensitive contains(rs), unless keep_non_rsid is explicitly true. The source divergent-P default replaces only infinite derived Z values using min(1e-50,smallest nonzero finite-P row); all-zero P inputs have no invented floor. Nonfinite Z rows are counted and excluded. Every excluded row and model SNP remains visible in the ledgers. Literal + or - signs, resolved uppercase model alleles and finite source effect sizes are required by this bounded workflow; other source-permissive ambiguous states are refused.\n\nCovariance is in raw dosage units and is assumed to use the supplied model effect alleles. Covariance/model-product files contain no allele/build authenticity proof: confirm their provider, models, ancestry, build and tissue labels before use. Source matrix axes use nonmissing id1 entries whose pair is in the intersection; all used pairs must exist. No missing pair is zero-filled. Summary variance uses only the USED SNP intersection. The native validation additionally requires a positive semidefinite matrix and finite positive model variance; source unreportable numerical cases fail rather than becoming successful null results. Genes lacking annotation/weights/aligned GWAS/covariance are counted explicitly in GENES.jsonl. A complete capture may contain such no-association dispositions. At least one finite association is required.\n\nJoint tests use the explicitly supplied model-product matrix and cutoff/regularization. Missing tissues are refused. Cutoffs precede regularization; the first singular component is always retained. The portable Java CPU backend is selected explicitly. Output includes log P; a zero tail P is counted, and joint source status-4 is retained for underflow. Numeric/identity memory and work bounds are conservative estimates, not a guarantee of available JVM heap; provision -Xmx appropriately. Table records are bounded to1Mi characters and1024 columns; decoded_bytes counts actual scans including the P-floor pass. Native time limits and cancellation checks are cooperative. SQLite's bundled native library needs a permitted executable temporary directory. No analysis-time download or installation occurs.\n\nSaved verification checks every byte and namespace member, then reads the captured databases/tables and recomputes every result and disposition with the exact producer JAR; it never accesses original host input paths. Retain producer JARs and private evidence. No whole-paper or full original-tool implementation is claimed.\n\n"+ACTION+"\n";
        if(!s.extended())return value;
        return value.replace("rsid is the model key; varID selection, identifier remapping, ","The model key is explicitly declared in settings.model_key; generic identifier remapping, ")
            + "\nSCHEMA2 KEY AND MATRIX CONTRACT: a null model_key.column keeps default rsid identifiers unchanged. An explicit existing column selects the original source-b38-first-row-rule: if the FIRST source ID contains _b38 and does not contain chr, the literal prefix chr is added to EVERY selected ID. This is an explicitly requested source operation, not a genome-build conversion. Requested/effective column, first original ID and applied flag are recorded in OUTPUT-AUDIT.json; source and effective IDs are retained in MODEL-SNPS.jsonl. Missing columns fail; no SNP_ID/varID/rsid alias is guessed. Extra matrix columns and their literal cells remain in MATRICES.jsonl and captured originals; only the original named matrix columns enter the calculation. additional_output=true adds best_gwas_p and largest_weight from the USED SNP intersection, before any gene-level phi correction. Old schema1 retains its prior contract.\n";
    }
    static void failure(Path root,String stage,Throwable e) {
        try{Files.deleteIfExists(root.resolve("COMPLETED.json"));if(!Files.exists(root.resolve("INCOMPLETE.json")))writeJson(root.resolve("INCOMPLETE.json"),Map.of("analysis_admitted",false));writeJson(root.resolve("FAILURE.json"),Map.of("status",unavailable(e)?"SKIP3_DEPENDENT_ANALYSIS_SKIPPED":"FAIL2_NO_COMPLETE_RESULT","stage",stage,"error",e.toString(),"required_action",ACTION));Files.writeString(root.resolve("WARNINGS.md"),"NO COMPLETE METAXCAN RESULT ADMITTED\n\n"+stage+": "+e+"\n\n"+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);}catch(IOException diagnostic){e.addSuppressed(diagnostic);}
    }
    static boolean unavailable(Throwable e){return e instanceof PredictDb.Unavailable||e instanceof MetaxcanRequest.Unavailable;}
    private static void require(boolean condition,String message)throws IOException{if(!condition)throw new IOException(message);}
}
